package com.ruoyi.medical.persistence;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import org.apache.ibatis.session.Configuration;import org.apache.ibatis.builder.xml.XMLMapperBuilder;import org.apache.ibatis.mapping.SqlCommandType;import net.sf.jsqlparser.parser.CCJSqlParserUtil;import net.sf.jsqlparser.statement.insert.Insert;import java.util.*;
public class RuntimeRetentionMapperTest {
 @Test void allActualSqlParsesAndReadsAreBounded()throws Exception{var c=new Configuration();try(var in=getClass().getResourceAsStream("/medical-mappers/RuntimeRetentionMapper.xml")){new XMLMapperBuilder(in,c,"retention",c.getSqlFragments()).parse();}var parameters=new HashMap<String,Object>();parameters.put("after","00000000-0000-4000-8000-000000000001");parameters.put("limit",28);int n=0;for(var name:c.getMappedStatementNames())if(name.startsWith("com.ruoyi.medical.persistence.mapper.RuntimeRetentionMapper.")){var ms=c.getMappedStatement(name);var sql=ms.getBoundSql(parameters).getSql();var parsed=CCJSqlParserUtil.parse(sql);if(sql.contains("operation_record")){assertTrue(sql.contains("subject_id"));assertFalse(sql.contains("user_id"));}if(ms.getSqlCommandType()==SqlCommandType.SELECT){assertEquals(5,ms.getTimeout());assertTrue(sql.toUpperCase().contains(" LIMIT "),name);assertFalse(ms.isUseCache());}if(parsed instanceof Insert insert){var values=(net.sf.jsqlparser.statement.select.Values)insert.getSelect();var expressions=(net.sf.jsqlparser.expression.operators.relational.ParenthesedExpressionList<?>)values.getExpressions();assertEquals(insert.getColumns().size(),expressions.size(),name);}if(name.endsWith(".retireState")){assertTrue(sql.contains("revision=?"));assertTrue(sql.contains("retired_at IS NULL"));assertTrue(sql.contains("decision_id IS NULL"));}n++;}assertEquals(28,n);}
 public static void main(String[]args)throws Exception{new RuntimeRetentionMapperTest().allActualSqlParsesAndReadsAreBounded();System.out.println("PASS actual 28 mapped SQL statements bounded/parsed/insert arity/CAS");}
}
